<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">ASSET</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                 READINGS
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <div class="row layout-top-spacing">
        <div class="d-flex">
            <div class="ms-auto">
                <button class="btn btn-primary m-2"
                data-bs-toggle="modal" data-bs-target="#register"
                @click="getRawData()"
                >
                <i class="bi bi-plus-square"></i>
                </button>
            </div>
        </div>
      <div v-if="loading" v-html="tableShimmer()"></div>
      <div 
      v-else
      class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
        <div class="panel p-0">
          <div class="custom-table table3">
            <v-client-table :data="readings" :columns="columns" >
            </v-client-table>
          </div>
        </div>
      </div>
    </div>
    </div>

    <!-- manual registration modla starts -->
     
                 <div class="modal fade mymodal" id="register" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">ASSET READING</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close-register" ></button>
      </div>
      <form @submit.prevent="saveReading()">
<div class="modal-body" >
      <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                      <div class="row">
                        <div class="col-md-4">
                          <label class="form-label">Asset List</label>
   <multiselect 
                    v-model="formData.asset"
                    :options= "assets"
                    label = "name"
                    placeholder="Select Item"
                    :required = "true"
                    :searchable = "true"        
                    multple="false"
                    ></multiselect>                        </div>

                           <div class="col-md-4">
                          <label class="form-label">Reading Location</label>
   <multiselect 
                    v-model="formData.location"
                    :options= "locations"
                    label = "name"
                    placeholder="Select Item"
                    :required = "true"
                    :searchable = "true"        
                    multple="false"
                    ></multiselect>         
                </div>

                                           <div class="col-md-4">
                          <label class="form-label">Odometer Reading</label>
<input type="number" step="any" class="form-control " :style="formData?.asset?.current_odometer_reading < formData.reading ? `border: 2px solid greenyellow;` :`border: 2px solid red;`" v-model="formData.reading" placeholder="Reading Value">  
<sub>Current Reading : {{ formData?.asset?.current_odometer_reading }}</sub>      
                </div>


                      </div>
                    </div>
                </div>
            </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger" data-bs-dismiss="modal">Close</button>
        <button type="submit" class="btn btn-success " :disabled="sending">
            <span v-if="sending" v-html="loadingSpinner()"></span>
            <span v-else>Save</span>
        </button>

      </div>
      </form>


    </div>
  </div>

</div>
     <!-- manual registration modal ends -->


</template>

<script setup>
import { ref, onMounted ,watch, inject } from 'vue'
import axios from 'axios'
import Multiselect from '@suadelabs/vue3-multiselect';
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
})

const loading = ref(false)
const formatDate = inject('formatDate')
const columns = ref(['Sno','asset', 'reading', 'source','read_by','time','location','actions']);
const readings = ref([])
const tableShimmer = inject('tableShimmer')
const getReadings = async () => {
    loading.value = true
    try{
const res = await axiosInstance.get('/readings')
  readings.value = res.data.map((item,index)=>({
    ...item,
   Sno : index + 1,
   asset :item?.subject?.asset?.name + ' - ' +item?.subject?.asset?.type_name ,
   reading : item?.reading_value,
   source : item?.reading_source,
   read_by : item?.handler,
   time : formatDate(item?.reading_time),
   location :item?.location?.name
  }))
    }finally{
     loading.value = false
    }
  
}

const formData = ref({
    asset : '',
    location : '',
    reading : ''
})
const asset = ref('')
const rawData = ref([])
const assets = ref([])
const locations = ref([])
const getRawData = async () =>{
  const response = await axiosInstance.get('/readings-raw-data')
  rawData.value = response.data
  assets.value = rawData.value.assets.map((item,index)=>({
    ...item,
   name :item?.name + ' - ' +item?.type_name ,
  }))

  locations.value = rawData.value.locations
}

const showError = inject('showError')
const loadingSpinner = inject('loadingSpinner')
const showMessage = inject('showMessage')
const sending = ref(false)
const saveReading = async()=>{
    sending.value = true
const now = new Date().toISOString();

const payload = {
    handler: JSON.parse(localStorage.getItem("user")).name,
    company_id: 6,
    reading_value: formData.value.reading,
    reading_source: 'MANUAL',
    location_id: formData.value.location.id,
    registrar_id: JSON.parse(localStorage.getItem("user")).id,
    asset_id: formData.value.asset.id,
    // reading_time: now
}
    try{
    const response = await axiosInstance.post('readings',payload)
    showMessage('reading Saved')
    document.getElementById('close-register').click()
    getReadings()
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        sending.value = false
    }

}


onMounted(() => {
  getReadings()
})
</script>